SELECT * FROM ( SELECT a.*, ROW_NUMBER() OVER (ORDER BY a.USER_NO) AS rnum FROM ( SELECT DISTINCT u.USER_NO, u.USER_PW, u.ENABLED, u.USER_CODE, u.USER_NM, u.USER_MAIL, u.USER_PHONE, u.USER_BIRTH, u.USER_INDATE, u.USER_PROFILE, u.USER_SIGN, u.USER_SYS_YN, u.USER_CREATE, u.USER_ADDR1, u.USER_ADDR2, u.USER_ZIP, e.DEPT_NO, d.DEPT_NM, e.POSITION_NO, p.POSITION_NM, e.EMP_MANAGER, FROM TEAM3_202407F.TB_USER u LEFT JOIN TEAM3_202407F.EMPLOYEE e ON u.USER_NO = e.USER_NO LEFT JOIN TEAM3_202407F.DEPT d ON e.DEPT_NO = d.DEPT_NO LEFT JOIN TEAM3_202407F.POSITION p ON e.POSITION_NO = p.POSITION_NO WHERE 1=1 AND USER_CODE IN (1,3)
AND ( UPPER(u.USER_NO) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(u.USER_NM) LIKE '%' || UPPER(#{keyword}) || '%' OR u.USER_PHONE LIKE '%' || #{keyword} || '%' )
AND e.DEPT_NO = #{deptNo}
AND e.POSITION_NO = #{positionNo}
) a ) b WHERE rnum BETWEEN (#{page} - 1) * #{size} + 1 AND #{page} * #{size}

